    with link = "point.dk.Dortheasminde", railway = :station {
        track(ht[:dor - 0.5sw, :dor + 0.5sw]);
        marker(:left :de.bf, ht[:dor] << 0.5mt);
        slabel(:right, ht[:dor] << 0.5mt << 1sh + (1.3dt, 1.8dt),
            "Dortheasminde"
        );
    }

    with link = "line.dk.HTG" {
        track(ht[:dor + 0.49sw, :uld - 0.49sw]);
    }

    with link = "point.dk.Uldum", railway = :station {
        track(ht[:uld - 0.5sw, :uld + 0.5sw]);
