        slabel(:bottom, ht[:von] << 0.5mt << 1sh + (-1dt, 0.5dt),
            "Vonge"
        );
    }

    with link = "line.dk.HTG" {
        track(ht[:von + 0.49sw, :kol - 0.49sw]);
    }

    with link = "point.dk.Kollemorten", railway = :station {
        track(ht[:kol - 0.5sw, :kol + 0.5sw]);
        marker(:left :de.bf, ht[:kol] << 0.5mt);
        slabel(:bottom, ht[:kol] << 0.5mt << 1sh + (-1dt, 0.3dt),
            "Kollemorten"
        );
    }

    with link = "line.dk.HTG" {
        track(ht[:kol + 0.49sw, :har - 0.49sw]);
